@import url('https://fonts.googleapis.com/css2?family=inter:wght@400;600;700&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #0A0A0A;
  font-family: "Inter", sans-serif;
}

#ad-320x480 {
  width: 320px;
  height: 480px;
  position: relative;
  overflow: hidden;
  background: #1F2A44;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  flex-shrink: 0;
}

/* ── Hero background ── */
.hero-bg {
  position: absolute;
  inset: 0;
  background: url('data:image/jpeg;base64,') center center / cover no-repeat;
  transform: scale(1.06);
  transition: transform 0.7s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 0;
  will-change: transform;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: rgba(31, 42, 68, 0.52);
  z-index: 1;
}

/* ── Diagonal accent strip ── */
#ad-320x480::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background: linear-gradient(
    -14deg,
    transparent 47.8%,
    rgba(236, 28, 36, 0.22) 48.2%,
    rgba(236, 28, 36, 0.22) 49.2%,
    transparent 49.6%
  );
}

/* ── Slices ── */
.slices-container {
  position: absolute;
  top: 62px;
  left: 0;
  right: 0;
  height: 160px;
  z-index: 7;
  pointer-events: none;
}

.slice {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  padding-left: 24px;
  transition: transform 0.6s cubic-bezier(0.77, 0, 0.18, 1), opacity 0.6s ease;
  will-change: transform, opacity;
  background: rgba(31, 42, 68, 0.88);
  opacity: 0;
  transform: translateX(110%);
  border-radius: 2px;
}

.slice-0 { clip-path: polygon(0% 18%, 100% 4%, 100% 82%, 0% 96%); }
.slice-1 { clip-path: polygon(0% 18%, 100% 4%, 100% 82%, 0% 96%); }
.slice-2 { clip-path: polygon(0% 18%, 100% 4%, 100% 82%, 0% 96%); }
.slice-3 { clip-path: polygon(0% 18%, 100% 4%, 100% 82%, 0% 96%); }

.slice.active {
  transform: translateX(0%);
  opacity: 1;
}

.slice.exit {
  transform: translateX(-110%);
  opacity: 0;
}

.slice-inner {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.stat-value {
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 33px;
  color: #FFFFFF;
  letter-spacing: -0.5px;
  line-height: 1.1;
  text-shadow: 0 2px 8px rgba(10, 10, 10, 0.7);
}

.stat-label {
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-size: 11px;
  color: #C8CED6;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  text-shadow: 0 1px 4px rgba(10, 10, 10, 0.5);
}

/* ── Header ── */
.ad-header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px 8px;
  background: linear-gradient(to bottom, rgba(10, 10, 10, 0.72) 0%, rgba(10, 10, 10, 0) 100%);
}

.brand-logo {
  height: 32px;
  max-height: 40px;
  width: auto;
  display: block;
}

.eyebrow {
  font-family: "Inter", sans-serif;
  font-weight: 600;
  font-size: 12px;
  letter-spacing: 2px;
  color: #C8CED6;
  text-transform: uppercase;
}

/* ── Progress bar ── */
.progress-bar-wrap {
  position: absolute;
  top: 54px;
  left: 16px;
  right: 16px;
  height: 2px;
  background: rgba(200, 206, 214, 0.22);
  border-radius: 2px;
  z-index: 10;
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  width: 25%;
  background: #EC1C24;
  border-radius: 2px;
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Headline ── */
.headline-wrap {
  position: absolute;
  top: 230px;
  left: 0;
  right: 0;
  z-index: 8;
  padding: 8px 20px 10px;
  background: linear-gradient(to bottom, rgba(10, 10, 10, 0) 0%, rgba(31, 42, 68, 0.72) 60%, rgba(31, 42, 68, 0.72) 100%);
}

.headline {
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 22px;
  color: #FFFFFF;
  letter-spacing: -0.5px;
  line-height: 1.25;
  margin-bottom: 4px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
}

.headline em {
  font-style: normal;
  color: #EC1C24;
}

.subhead {
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-size: 12px;
  color: #C8CED6;
  letter-spacing: 0.2px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
}

/* ── Car image ── */
.car-img-wrap {
  position: absolute;
  bottom: 108px;
  left: -20px;
  right: -20px;
  z-index: 5;
  pointer-events: none;
  transition: transform 0.65s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: transform;
}

.car-img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
  object-position: center 60%;
  filter: drop-shadow(0 10px 28px rgba(10, 10, 10, 0.7));
}

/* ── Step dots ── */
.step-dots {
  position: absolute;
  bottom: 122px;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
}

.dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(200, 206, 214, 0.38);
  transition: background 0.3s ease, transform 0.3s ease;
  cursor: pointer;
}

.dot.active {
  background: #EC1C24;
  transform: scale(1.35);
}

/* ── Tap hint ── */
.tap-hint {
  position: absolute;
  bottom: 140px;
  left: 0;
  right: 0;
  z-index: 10;
  text-align: center;
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-size: 10px;
  color: rgba(200, 206, 214, 0.6);
  letter-spacing: 0.6px;
  text-transform: uppercase;
  animation: hintPulse 2s ease-in-out infinite;
  transition: opacity 0.5s ease;
}

@keyframes hintPulse {
  0%, 100% { opacity: 0.45; }
  50% { opacity: 1; }
}

.tap-hint.hidden {
  opacity: 0;
  pointer-events: none;
  animation: none;
}

/* ── Footer / CTA ── */
.ad-footer {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 10;
  padding: 12px 16px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  background: linear-gradient(to top, rgba(10, 10, 10, 0.88) 0%, rgba(10, 10, 10, 0) 100%);
}

.cta-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #EC1C24;
  color: #FFFFFF;
  text-decoration: none;
  border-radius: 4px;
  padding: 11px 20px;
  width: 100%;
  transition: background 0.2s ease, transform 0.15s ease;
}

.cta-btn:hover,
.cta-btn:focus {
  background: #7A0E14;
  transform: translateY(-1px);
  outline: none;
}

.cta-btn:active {
  transform: translateY(0);
}

.cta-label {
  font-family: "Inter", sans-serif;
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.3px;
  color: #FFFFFF;
  white-space: nowrap;
}

.body-copy {
  font-family: "Inter", sans-serif;
  font-style: italic;
  font-weight: 400;
  font-size: 9px;
  color: #5B7CA8;
  text-align: center;
  line-height: 1.4;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.5);
}

/* ── CTA pulse on last step ── */
.cta-btn.pulse {
  animation: ctaPulse 1.5s ease-in-out infinite;
}

@keyframes ctaPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(236, 28, 36, 0.55); }
  50% { box-shadow: 0 0 0 8px rgba(236, 28, 36, 0); }
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .slice,
  .car-img-wrap,
  .hero-bg,
  .progress-bar,
  .tap-hint,
  .cta-btn {
    transition: none;
    animation: none;
  }
}

